insert into public.soal_l1 (id, tipe, item, opts, ans, topic, why, hint) values
  ('a1', 'basket', 'Reksa Dana Pasar Uang', null, 'likuid', 'nabung', 'Reksa dana pasar uang berisi instrumen jatuh tempo di bawah satu tahun dan bisa dicairkan dalam hitungan hari kerja dengan nilai relatif stabil, sehingga lazim dipakai sebagai wadah dana darurat.', 'Perhatikan berapa cepat instrumen ini bisa menjadi uang tunai dan seberapa stabil nilainya saat dicairkan.'),
  ('a2', 'basket', 'Tabungan di Bank', null, 'likuid', 'nabung', 'Tabungan bisa ditarik kapan saja tanpa kehilangan nilai pokok, sehingga termasuk aset paling likuid.', 'Pikirkan apakah uang ini bisa kamu ambil hari ini juga tanpa potongan.'),
  ('a3', 'basket', 'Cicilan KPR', null, 'utang', 'utang', 'Cicilan KPR adalah kewajiban membayar pinjaman kepada bank setiap bulan. Rumahnya aset, tetapi cicilannya adalah utang.', 'Bedakan antara barang yang kamu miliki dan kewajiban yang harus kamu bayar setiap bulan.'),
  ('a4', 'basket', 'Saham Perusahaan Tbk', null, 'invest', 'investasi', 'Saham dibeli untuk mendapat dividen dan kenaikan harga jangka panjang. Nilainya berfluktuasi sehingga tidak cocok dianggap dana siap pakai.', 'Tanyakan: tujuan membelinya untuk berjaga-jaga atau untuk menumbuhkan nilai dalam jangka panjang?'),
  ('a5', 'basket', 'Tagihan Kartu Kredit', null, 'utang', 'utang', 'Tagihan kartu kredit adalah pinjaman jangka pendek yang wajib dilunasi dan berbunga tinggi jika tidak dibayar penuh.', 'Ingat siapa yang sebenarnya membayar belanjaanmu lebih dulu saat memakai kartu ini.'),
  ('a6', 'basket', 'Emas Batangan', null, 'invest', 'investasi', 'Emas batangan disimpan untuk menjaga nilai dalam jangka menengah hingga panjang. Ada spread harga jual dan buyback, sehingga kurang ideal untuk kebutuhan mendadak.', 'Pertimbangkan biaya dan selisih harga saat emas harus dijual cepat.'),
  ('a7', 'basket', 'Deposito 1 Bulan', null, 'likuid', 'nabung', 'Deposito bertenor pendek dijamin LPS dalam batas ketentuan dan cepat jatuh tempo, sehingga tergolong aset likuid untuk dana darurat.', 'Perhatikan tenornya: berapa lama sampai uangnya kembali utuh?'),
  ('a8', 'basket', 'Obligasi Ritel (ORI)', null, 'invest', 'investasi', 'ORI memberi kupon berkala sampai jatuh tempo beberapa tahun. Tujuannya pendapatan dan pertumbuhan, bukan dana siap pakai.', 'Lihat jangka waktunya dan tujuan utama memegang instrumen ini.'),
  ('a9', 'basket', 'Paylater Belanja Daring', null, 'utang', 'utang', 'Paylater adalah pinjaman yang harus dibayar kembali, sering disertai biaya atau bunga. Riwayat pembayarannya juga tercatat di SLIK.', '"Bayar nanti" berarti ada kewajiban yang menunggumu.'),
  ('a10', 'basket', 'Uang Tunai di Dompet', null, 'likuid', 'dasar', 'Uang tunai adalah bentuk aset paling likuid karena langsung bisa dipakai bertransaksi.', 'Ini bentuk paling sederhana dari aset. Seberapa cepat bisa dipakai?'),
  ('a11', 'basket', 'Reksa Dana Saham', null, 'invest', 'investasi', 'Reksa dana saham ditujukan untuk jangka panjang karena nilainya bisa naik turun tajam dalam jangka pendek.', 'Isi portofolionya menentukan jawabannya. Seberapa besar nilainya bisa berayun?'),
  ('a12', 'basket', 'Pinjaman Koperasi', null, 'utang', 'utang', 'Pinjaman dari koperasi tetap merupakan kewajiban yang harus dicicil beserta jasa atau bunganya.', 'Sumber pinjamannya tidak mengubah sifatnya.'),
  ('p1', 'pg', 'Prinsip "bayar diri sendiri dulu" dalam mengatur gaji berarti…', '["Menabung dari sisa belanja di akhir bulan", "Menyisihkan tabungan begitu gaji masuk", "Membeli kebutuhan pribadi lebih dulu", "Melunasi semua utang sebelum boleh menabung"]'::jsonb, '1', 'dasar', 'Tabungan disisihkan di awal, baru sisanya dibelanjakan. Menabung dari sisa belanja cenderung gagal karena pengeluaran menyesuaikan saldo yang ada.', 'Perhatikan kapan tabungan disisihkan: sebelum atau sesudah belanja?'),
  ('p2', 'pg', 'Ukuran yang paling menggambarkan kesehatan keuangan seseorang adalah…', '["Besar gaji bulanan", "Jumlah kartu kredit yang dimiliki", "Kekayaan bersih (aset dikurangi utang)", "Saldo rekening pada hari gajian"]'::jsonb, '2', 'dasar', 'Gaji besar bisa habis untuk cicilan. Kekayaan bersih menunjukkan berapa yang benar-benar dimiliki setelah semua utang diperhitungkan.', 'Mana yang sudah memperhitungkan aset sekaligus utang?'),
  ('p3', 'pg', 'Tempat paling tepat untuk menyimpan dana darurat adalah…', '["Saham perusahaan besar", "Tabungan terpisah atau reksa dana pasar uang", "Emas batangan", "Properti sewaan"]'::jsonb, '1', 'nabung', 'Dana darurat perlu aman dan cepat dicairkan tanpa banyak kehilangan nilai. Saham dan emas bisa turun atau terkena spread, properti sulit dijual cepat.', 'Dua syarat dana darurat: nilainya stabil dan bisa cair cepat.'),
  ('p4', 'pg', 'Manakah yang termasuk penggunaan dana darurat yang tepat?', '["Liburan akhir tahun", "Membeli ponsel baru saat diskon", "Biaya rawat inap yang mendadak", "Uang muka kendaraan baru"]'::jsonb, '2', 'nabung', 'Dana darurat untuk kejadian mendesak yang tidak direncanakan, seperti sakit atau kehilangan penghasilan. Liburan dan belanja bisa direncanakan dengan tabungan tujuan.', 'Mana yang mendesak sekaligus tidak bisa direncanakan sebelumnya?'),
  ('p5', 'pg', 'SLIK OJK berfungsi untuk…', '["Mencatat riwayat kredit setiap debitur", "Menjamin simpanan nasabah bank", "Memberi izin kepada pinjaman daring", "Menetapkan suku bunga kredit"]'::jsonb, '0', 'utang', 'SLIK (Sistem Layanan Informasi Keuangan) mencatat riwayat kredit. Lembaga keuangan memeriksanya sebelum menyetujui pinjaman baru.', 'Ingat apa yang dicek bank saat kamu mengajukan KPR.'),
  ('p6', 'pg', 'Strategi melunasi utang berbunga tertinggi lebih dulu agar total bunga paling hemat disebut metode…', '["Snowball", "Avalanche", "Top up", "Gali lubang tutup lubang"]'::jsonb, '1', 'utang', 'Metode avalanche mendahulukan bunga tertinggi sehingga total bunga paling kecil. Snowball mendahulukan saldo terkecil untuk motivasi.', 'Satu metode fokus pada bunga, satu lagi fokus pada saldo terkecil.'),
  ('p7', 'pg', 'Tujuan utama diversifikasi investasi adalah…', '["Menjamin keuntungan setiap tahun", "Mengurangi risiko dengan menyebar dana ke beberapa aset", "Memperbesar pinjaman untuk berinvestasi", "Mempercepat pencairan dana"]'::jsonb, '1', 'investasi', 'Diversifikasi menyebar dana agar kerugian di satu aset dapat diimbangi aset lain. Tidak ada investasi yang menjamin untung.', '"Jangan taruh semua telur di satu keranjang."'),
  ('p8', 'pg', 'Hal berikut memengaruhi profil risiko seseorang, KECUALI…', '["Usia", "Tujuan dan jangka waktu investasi", "Kondisi keuangan", "Merek ponsel yang dipakai"]'::jsonb, '3', 'investasi', 'Profil risiko dipengaruhi usia, tujuan, jangka waktu, dan kondisi keuangan. Merek ponsel tidak ada hubungannya.', 'Cari pilihan yang tidak berkaitan dengan kemampuan menanggung penurunan nilai.'),
  ('p9', 'pg', 'Dalam asuransi, "premi" adalah…', '["Nilai manfaat yang dibayar saat klaim", "Biaya berkala yang dibayar pemegang polis", "Dokumen kontrak asuransi", "Periode tunggu sebelum manfaat aktif"]'::jsonb, '1', 'asuransi', 'Premi adalah biaya berkala. Manfaat saat klaim disebut uang pertanggungan, kontraknya disebut polis.', 'Mana yang kamu bayar, bukan yang kamu terima?'),
  ('p10', 'pg', 'Asuransi jiwa paling penting dimiliki oleh…', '["Lajang tanpa tanggungan", "Pencari nafkah utama yang punya tanggungan", "Pensiunan tanpa tanggungan", "Mahasiswa yang belum bekerja"]'::jsonb, '1', 'asuransi', 'Asuransi jiwa menggantikan penghasilan yang hilang. Paling penting bagi orang yang penghasilannya diandalkan keluarga.', 'Siapa yang paling dirugikan jika penghasilan seseorang tiba-tiba hilang?'),
  ('p11', 'pg', 'Program BPJS Ketenagakerjaan berupa tabungan hari tua yang dibayarkan sekaligus adalah…', '["Jaminan Pensiun (JP)", "Jaminan Hari Tua (JHT)", "Jaminan Kecelakaan Kerja (JKK)", "Jaminan Kematian (JKM)"]'::jsonb, '1', 'pensiun', 'JHT dibayar sekaligus, sedangkan JP memberi manfaat bulanan bagi peserta yang memenuhi syarat.', 'Satu program dibayar sekaligus, satu lagi dibayar bulanan.'),
  ('p12', 'pg', 'Prinsip 2L untuk menguji tawaran investasi adalah…', '["Laba dan Likuid", "Legal dan Logis", "Lancar dan Lunas", "Lokal dan Lengkap"]'::jsonb, '1', 'ilegal', 'Legal: lembaga dan produknya berizin. Logis: imbal hasilnya masuk akal dan sebanding dengan risiko.', 'Satu L soal izin, satu L soal masuk akal atau tidak.'),
  ('b1', 'bs', 'Kalau sudah ada teman yang berhasil mencairkan keuntungan, investasi tersebut pasti legal.', null, 'salah', 'ilegal', 'Pencairan di awal sering dipakai skema Ponzi untuk memancing anggota baru. Legalitas hanya bisa dipastikan lewat izin otoritas.', 'Dari mana skema Ponzi membayar "keuntungan" anggota lama?'),
  ('b2', 'bs', 'Simpanan di bank peserta LPS dijamin hingga Rp2 miliar per nasabah per bank.', null, 'benar', 'nabung', 'Benar, selama bunga simpanan tidak melebihi tingkat bunga penjaminan LPS.', 'Ingat lembaga yang menjamin simpanan nasabah bank.'),
  ('b3', 'bs', 'Membayar tagihan minimum kartu kredit membuat sisa tagihan tidak dikenai bunga.', null, 'salah', 'utang', 'Sisa tagihan tetap berbunga setiap bulan, sehingga utang lama lunas dan total bunga membengkak.', 'Apa yang terjadi pada tagihan yang belum dibayar penuh?'),
  ('b4', 'bs', 'Imbal hasil investasi sebaiknya lebih tinggi dari inflasi agar daya beli uang terjaga.', null, 'benar', 'investasi', 'Jika imbal hasil di bawah inflasi, nilai riil uang turun walau nominalnya bertambah.', 'Bandingkan kenaikan nilai uangmu dengan kenaikan harga barang.'),
  ('b5', 'bs', 'Unit link memberikan hasil investasi yang dijamin.', null, 'salah', 'asuransi', 'Unit link menggabungkan proteksi dan investasi. Hasil investasinya mengikuti pasar dan tidak dijamin.', 'Bagian investasinya ditempatkan di mana? Apakah pasar bisa turun?'),
  ('b6', 'bs', 'Dana pensiun sebaiknya dicairkan lebih awal untuk kebutuhan mendesak.', null, 'salah', 'pensiun', 'Penarikan dini memotong efek bunga majemuk. Kebutuhan mendesak sebaiknya ditutup dari dana darurat.', 'Untuk kebutuhan mendesak, sudah ada pos dana khusus.'),
  ('b7', 'bs', 'Rumah dan kendaraan termasuk aset tidak likuid.', null, 'benar', 'dasar', 'Keduanya butuh waktu dan biaya untuk dijual, berbeda dengan tabungan yang bisa dicairkan seketika.', 'Seberapa cepat aset ini bisa menjadi uang tunai?'),
  ('b8', 'bs', 'Kode OTP boleh diberikan kepada petugas yang mengaku dari bank lewat telepon.', null, 'salah', 'aman', 'Petugas resmi tidak pernah meminta OTP, PIN, atau password. Permintaan seperti itu adalah modus penipuan.', 'OTP adalah kunci terakhir rekeningmu. Siapa yang berhak tahu?'),
  ('h1', 'hitung', 'Gaji bersih Rp8.000.000. Dengan pola 50/30/20, berapa porsi untuk tabungan dan investasi?', '["Rp800.000", "Rp1.600.000", "Rp2.400.000", "Rp4.000.000"]'::jsonb, '1', 'dasar', '20% × Rp8.000.000 = Rp1.600.000.', 'Pos tabungan pada pola 50/30/20 adalah 20%.'),
  ('h2', 'hitung', 'Total aset Rp150 juta dan total utang Rp60 juta. Berapa kekayaan bersihnya?', '["Rp60 juta", "Rp90 juta", "Rp150 juta", "Rp210 juta"]'::jsonb, '1', 'dasar', 'Kekayaan bersih = aset − utang = Rp150 juta − Rp60 juta = Rp90 juta.', 'Kurangkan, jangan dijumlahkan.'),
  ('h3', 'hitung', 'Pengeluaran Rp5 juta per bulan, sudah menikah, punya 1 anak. Panduan: 6 bulan + 1 bulan per anak. Berapa target dana daruratnya?', '["Rp15 juta", "Rp30 juta", "Rp35 juta", "Rp60 juta"]'::jsonb, '2', 'nabung', '(6 + 1) bulan × Rp5 juta = Rp35 juta.', 'Hitung dulu jumlah bulannya, lalu kalikan pengeluaran.'),
  ('h4', 'hitung', 'Penghasilan bersih Rp10 juta per bulan. Berapa batas aman total cicilan (30%)?', '["Rp1 juta", "Rp3 juta", "Rp5 juta", "Rp7 juta"]'::jsonb, '1', 'utang', '30% × Rp10 juta = Rp3 juta per bulan.', 'Batas aman cicilan adalah 30% penghasilan bersih.'),
  ('h5', 'hitung', 'Total cicilan Rp4,5 juta dari penghasilan bersih Rp9 juta. Berapa rasio cicilannya?', '["25%", "30%", "45%", "50%"]'::jsonb, '3', 'utang', 'Rp4,5 juta ÷ Rp9 juta × 100% = 50%, jauh di atas batas aman 30%.', 'Bagi total cicilan dengan penghasilan bersih.'),
  ('h6', 'hitung', 'Dengan Rule of 72, uang yang tumbuh 6% per tahun menjadi dua kali lipat dalam sekitar…', '["6 tahun", "9 tahun", "12 tahun", "18 tahun"]'::jsonb, '2', 'investasi', '72 ÷ 6 = 12 tahun.', 'Bagi 72 dengan imbal hasil tahunan.'),
  ('h7', 'hitung', 'Bunga kartu kredit 1,75% per bulan (batas maksimum dari BI) setara berapa persen per tahun (tanpa bunga majemuk)?', '["1,75%", "12%", "21%", "30%"]'::jsonb, '2', 'utang', '1,75% × 12 bulan = 21% per tahun, jauh di atas imbal hasil investasi yang wajar.', 'Satu tahun ada 12 bulan.'),
  ('h8', 'hitung', 'Penghasilan tahunan Rp120 juta. Panduan uang pertanggungan jiwa sekitar 10 kali penghasilan tahunan adalah…', '["Rp120 juta", "Rp600 juta", "Rp1,2 miliar", "Rp12 miliar"]'::jsonb, '2', 'asuransi', '10 × Rp120 juta = Rp1,2 miliar.', 'Kalikan penghasilan tahunan dengan 10.'),
  ('p13', 'pg', 'Biaya MDR pada transaksi QRIS ditanggung oleh…', '["Pembeli", "Pedagang", "Bank Indonesia", "Dibagi dua antara pembeli dan pedagang"]'::jsonb, '1', 'digital', 'MDR ditanggung pedagang. Bank Indonesia menegaskan pedagang tidak boleh membebankannya kepada pembeli.', 'Ingat siapa yang menerima dana dan memakai layanan QRIS untuk usahanya.'),
  ('p14', 'pg', 'Kamu menerima file "Undangan_Pernikahan.apk" lewat chat. Sikap yang tepat adalah…', '["Membukanya jika dikirim kenalan", "Memasangnya untuk melihat undangan", "Tidak memasangnya karena file .apk bisa mencuri OTP dan data", "Meneruskannya ke grup agar yang lain tahu acaranya"]'::jsonb, '2', 'aman', 'File .apk adalah aplikasi. Jika dipasang, aplikasi itu bisa membaca SMS termasuk OTP sehingga rekening dapat dikuras.', 'Undangan asli biasanya berbentuk gambar atau PDF, bukan aplikasi.'),
  ('p15', 'pg', 'Manakah tujuan keuangan yang memenuhi kriteria SMART?', '["Ingin cepat kaya", "Ingin punya rumah suatu hari nanti", "Mengumpulkan uang muka rumah Rp100 juta dalam 4 tahun", "Menabung sebanyak mungkin"]'::jsonb, '2', 'tujuan', 'Tujuan SMART jelas, terukur dalam rupiah, realistis, relevan, dan punya tenggat waktu.', 'Cari pilihan yang punya angka sekaligus tenggat.'),
  ('b9', 'bs', 'Biaya maksimal transfer antarbank lewat BI-FAST adalah Rp2.500 per transaksi.', null, 'benar', 'digital', 'Benar. BI-FAST memproses transfer real-time 24/7 dengan biaya maksimal Rp2.500 yang boleh dikenakan bank.', 'Ingat infrastruktur transfer cepat milik Bank Indonesia.'),
  ('b10', 'bs', 'Setelah sadar tertipu transfer, sebaiknya menunggu beberapa hari dulu sebelum melapor ke bank.', null, 'salah', 'aman', 'Laporan secepatnya ke bank dan IASC memperbesar peluang dana di rekening pelaku sempat diblokir.', 'Seberapa cepat pelaku biasanya memindahkan uang hasil penipuan?'),
  ('h9', 'hitung', 'Biaya kuliah hari ini Rp50 juta dan naik 10% per tahun. Kira-kira berapa biayanya 2 tahun lagi?', '["Rp55 juta", "Rp60 juta", "Rp60,5 juta", "Rp70 juta"]'::jsonb, '2', 'tujuan', 'Rp50 juta × 1,1 × 1,1 = Rp60,5 juta. Kenaikan tahun kedua dihitung dari biaya yang sudah naik.', 'Kenaikannya bertumpuk setiap tahun, bukan sekadar 10% + 10%.'),
  ('a13', 'basket', 'Saldo Dompet Digital', null, 'likuid', 'digital', 'Saldo uang elektronik bisa langsung dipakai bertransaksi sehingga termasuk aset likuid. Ingat, saldonya tidak dijamin LPS.', 'Seberapa cepat saldo ini bisa dipakai untuk membayar?')
insert into public.soal_l2 (id, who, topics, story, ask, opts, ok, why, hint) values
  ('c1', 'Sari', array['utang','ilegal']::text[], 'Sari menerima bonus tahunan Rp15 juta. Ia belum punya dana darurat, masih menyicil kartu kredit Rp6 juta dengan bunga 1,75% per bulan, dan tergoda ikut arisan saham yang menjanjikan imbal hasil 8% per bulan.', 'Langkah paling tepat bagi Sari adalah:', '["Menempatkan seluruh bonus di arisan saham agar cicilan kartu kredit cepat lunas dari hasilnya.", "Melunasi kartu kredit lebih dulu, lalu menyisihkan sisanya sebagai dana darurat.", "Menyimpan semua bonus di deposito dan membiarkan cicilan kartu kredit berjalan.", "Membagi rata bonus ke arisan saham, deposito, dan cicilan kartu kredit."]'::jsonb, 1, 'Bunga kartu kredit 1,75% per bulan setara 21% per tahun, jauh di atas imbal hasil wajar mana pun. Melunasinya memberi hasil pasti sebesar bunga yang dihindari. Tawaran 8% per bulan tanpa izin usaha adalah ciri umum investasi ilegal.', 'Bandingkan bunga utang dengan imbal hasil yang realistis, lalu cek apakah tawaran arisan itu Legal dan Logis.'),
  ('c2', 'Budi', array['asuransi']::text[], 'Budi (29 tahun) sudah menikah dan punya satu anak balita. Penghasilannya Rp9 juta per bulan dan menjadi satu-satunya sumber nafkah keluarga. Saat ini ia hanya punya BPJS Kesehatan.', 'Proteksi tambahan yang paling tepat untuk Budi adalah:', '["Asuransi pendidikan anak dengan premi Rp2 juta per bulan.", "Unit link dengan premi Rp1,5 juta agar sekaligus berinvestasi.", "Asuransi jiwa berjangka dengan uang pertanggungan sekitar 10 kali penghasilan tahunan.", "Tidak perlu asuransi tambahan, cukup menabung lebih banyak."]'::jsonb, 2, 'Risiko terbesar keluarga Budi adalah hilangnya penghasilan jika terjadi sesuatu padanya. Asuransi jiwa berjangka memberi uang pertanggungan besar dengan premi terjangkau, sementara kebutuhan kesehatan dasar sudah ditanggung BPJS Kesehatan.', 'Cari tahu risiko apa yang paling berat dampaknya bagi keluarga yang bergantung pada satu penghasilan.'),
  ('c3', 'Dimas', array['nabung']::text[], 'Dimas masih lajang dengan pengeluaran Rp4 juta per bulan. Seluruh tabungannya, Rp20 juta, tersimpan di rekening gaji dan sering terpakai untuk belanja tanpa sadar.', 'Pengaturan yang paling tepat untuk Dimas adalah:', '["Memindahkan Rp12 juta ke rekening terpisah atau reksa dana pasar uang sebagai dana darurat, lalu sisanya dialokasikan sesuai tujuan.", "Memindahkan seluruh Rp20 juta ke saham agar tumbuh lebih cepat.", "Membiarkan semuanya di rekening gaji supaya mudah diambil kapan saja.", "Membelikan semuanya emas batangan sebagai dana darurat."]'::jsonb, 0, 'Untuk lajang, dana darurat ideal sekitar 3 bulan pengeluaran, yaitu Rp12 juta. Menyimpannya terpisah di instrumen likuid menjaga dana tetap aman dan tidak terpakai untuk belanja harian.', 'Hitung dulu target dana darurat untuk lajang, lalu pikirkan tempat yang aman sekaligus cepat dicairkan.'),
  ('c4', 'Rina', array['ilegal']::text[], 'Rina diajak rekan kerja ikut "arisan donasi" daring yang menjanjikan keuntungan 30% dalam dua minggu. Katanya sudah banyak anggota yang dananya cair, dan bonus tambahan diberikan jika berhasil mengajak teman.', 'Sikap yang paling tepat bagi Rina adalah:', '["Ikut dengan nominal kecil dulu untuk menguji.", "Ikut karena yang mengajak adalah rekan kerja yang dipercaya.", "Mengajak teman lain agar mendapat bonus rekrutmen.", "Menolak, memeriksa legalitasnya, lalu melaporkan ke Kontak OJK 157 atau Satgas PASTI."]'::jsonb, 3, 'Imbal hasil 30% dalam dua minggu tidak logis, dan bonus rekrutmen adalah ciri skema Ponzi. Pencairan awal sering dipakai untuk memancing korban baru. Langkah yang tepat adalah menolak dan melapor.', 'Uji tawarannya dengan prinsip 2L dan perhatikan dari mana "keuntungan" anggota lama dibayar.'),
  ('c5', 'Andi', array['utang']::text[], 'Andi berpenghasilan bersih Rp10 juta per bulan dan sedang mencicil motor Rp1,2 juta. Ia ingin mengambil KPR dengan cicilan Rp3,5 juta per bulan.', 'Penilaian yang paling tepat atas rencana Andi adalah:', '["Aman, karena total cicilan 47% masih di bawah setengah penghasilan.", "Total cicilan menjadi 47%, di atas batas aman 30%. Andi sebaiknya memilih cicilan lebih kecil atau menambah uang muka.", "Aman, asalkan kekurangan bulanan ditutup dengan kartu kredit.", "Aman, jika uang muka dipinjam dari pinjaman daring."]'::jsonb, 1, '(Rp1,2 juta + Rp3,5 juta) ÷ Rp10 juta = 47%, jauh di atas panduan 30%. Menutup kekurangan dengan utang baru justru menambah beban bunga.', 'Jumlahkan seluruh cicilan lalu bagi dengan penghasilan bersih. Bandingkan hasilnya dengan batas aman.'),
  ('c6', 'Maya', array['pensiun','investasi']::text[], 'Maya berusia 25 tahun dan baru setahun bekerja. Ia ingin punya dana pensiun yang cukup, tetapi merasa gajinya masih kecil untuk mulai menyisihkan.', 'Saran yang paling tepat bagi Maya adalah:', '["Menunggu usia 40 tahun saat gaji sudah besar.", "Cukup mengandalkan JHT dari BPJS Ketenagakerjaan.", "Mulai sekarang dengan setoran rutin kecil ke DPLK atau reksa dana jangka panjang.", "Menyimpan sisa gaji di tabungan biasa tanpa target."]'::jsonb, 2, 'Waktu adalah faktor terbesar bunga majemuk. Setoran kecil yang dimulai di usia 25 tahun bisa menghasilkan nilai lebih besar dibanding setoran besar yang baru dimulai di usia 40 tahun.', 'Ingat konsep bunga majemuk: apa yang paling menentukan besar nilai akhirnya?'),
  ('c7', 'Wulan', array['nabung']::text[], 'Wulan menerima THR Rp6 juta. Ia belum punya dana darurat sama sekali, sementara teman-temannya mengajak liburan ke Bali dengan biaya sekitar Rp5 juta.', 'Keputusan yang paling bijak bagi Wulan adalah:', '["Ikut liburan, dana darurat bisa dikumpulkan bulan depan.", "Menjadikan sebagian besar THR sebagai awal dana darurat, lalu merencanakan liburan dengan tabungan khusus.", "Ikut liburan dengan cicilan paylater agar THR tetap utuh.", "Menyimpan THR di rekening gaji tanpa rencana."]'::jsonb, 1, 'Tanpa dana darurat, kejadian mendadak bisa memaksa Wulan berutang. THR adalah kesempatan baik untuk memulai bantalan keuangan. Liburan tetap bisa dicapai lewat tabungan tujuan.', 'Pikirkan apa yang terjadi bila ada kebutuhan mendesak setelah uangnya habis untuk liburan.'),
  ('c8', 'Fajar', array['utang','ilegal']::text[], 'Fajar butuh Rp3 juta untuk biaya servis motor. Ia menerima SMS tawaran pinjaman daring "cair 5 menit tanpa syarat" dari aplikasi yang tidak ia kenal, yang meminta akses ke seluruh kontak ponselnya.', 'Langkah yang paling tepat bagi Fajar adalah:', '["Mengambil pinjaman itu karena prosesnya cepat.", "Mengambil pinjaman, lalu segera mencabut izin akses kontak.", "Memastikan penyelenggara berizin OJK sebagai LPBBTI dan mencari alternatif seperti koperasi kantor atau dana darurat.", "Meminjam di dua aplikasi sekaligus agar bunganya terbagi."]'::jsonb, 2, 'Tawaran lewat SMS tanpa syarat dan meminta akses kontak adalah ciri pinjaman daring ilegal. Pinjaman daring legal wajib berizin OJK dan hanya boleh mengakses kamera, mikrofon, dan lokasi.', 'Cek legalitas penyelenggara dan perhatikan izin akses yang diminta aplikasi.'),
  ('c9', 'Lina', array['investasi']::text[], 'Lina ingin mengumpulkan uang muka rumah dalam 2 tahun. Profil risikonya moderat dan ia tidak ingin nilai tabungannya turun tajam menjelang waktu pembelian.', 'Pilihan instrumen yang paling sesuai untuk Lina adalah:', '["Seluruhnya di reksa dana saham agar hasilnya maksimal.", "Reksa dana pasar uang atau pendapatan tetap, atau SBN ritel yang jatuh temponya sesuai.", "Saham satu perusahaan yang sedang ramai dibicarakan.", "Aset kripto karena potensi kenaikannya tinggi."]'::jsonb, 1, 'Untuk tujuan 2 tahun, instrumen berisiko rendah sampai menengah lebih cocok karena nilainya relatif stabil. Saham dan kripto bisa turun tajam tepat saat dana dibutuhkan.', 'Cocokkan jangka waktu tujuan dengan seberapa besar instrumen itu bisa berfluktuasi.'),
  ('c10', 'Pak Harto', array['pensiun']::text[], 'Pak Harto akan pensiun 6 tahun lagi. Ia belum pernah menghitung kebutuhan pensiunnya dan tabungannya masih jauh dari cukup.', 'Langkah pertama yang paling tepat adalah:', '["Menaruh semua tabungan di investasi berisiko tinggi agar cepat terkejar.", "Menghitung kebutuhan pensiun, mengecek saldo JHT dan JP, lalu menambah setoran rutin sesuai kekurangannya.", "Mengandalkan anak untuk membiayai masa pensiun.", "Mencairkan JHT sekarang untuk modal usaha."]'::jsonb, 1, 'Tanpa angka target, sulit mengetahui besar kekurangannya. Dengan waktu 6 tahun, menambah setoran rutin di instrumen yang sesuai lebih aman daripada mengejar hasil tinggi berisiko besar.', 'Apa yang perlu diketahui lebih dulu sebelum memilih instrumen?'),
  ('c11', 'Tika', array['asuransi']::text[], 'Tika (27 tahun, lajang, tanpa tanggungan) ditawari agen unit link dengan premi Rp1,5 juta per bulan. Ia sudah punya BPJS Kesehatan dan dana darurat 3 bulan.', 'Penilaian yang paling tepat adalah:', '["Langsung ambil karena sekaligus investasi.", "Pertimbangkan kebutuhan proteksinya dulu. Tanpa tanggungan, asuransi jiwa besar belum mendesak dan investasi bisa dipisah.", "Ambil dua polis unit link agar hasilnya berlipat.", "Batalkan BPJS Kesehatan lalu ganti dengan unit link."]'::jsonb, 1, 'Asuransi jiwa paling penting bagi yang punya tanggungan. Unit link berpremi tinggi dan hasil investasinya tidak dijamin, sehingga lebih fleksibel memisahkan proteksi dan investasi.', 'Untuk siapa asuransi jiwa paling dibutuhkan?'),
  ('c12', 'Reza', array['ilegal','investasi']::text[], 'Reza ditawari aplikasi robot trading yang menjanjikan profit tetap 1% per hari. Pendaftaran butuh deposit Rp5 juta dan ada bonus jika berhasil mengajak teman.', 'Sikap yang paling tepat bagi Reza adalah:', '["Deposit kecil dulu untuk mencoba.", "Ikut karena sudah banyak testimoni di media sosial.", "Menolak, karena profit tetap 1% per hari tidak logis dan skema bonus rekrutmen adalah tanda bahaya, lalu cek ke Kontak OJK 157.", "Ikut dan segera mengajak teman agar modal cepat kembali."]'::jsonb, 2, 'Profit 1% per hari setara ratusan persen setahun, tidak masuk akal. Ditambah bonus rekrutmen, tawaran ini memenuhi ciri investasi ilegal.', 'Hitung 1% per hari menjadi setahun, lalu uji dengan prinsip 2L.'),
  ('c13', 'Nia', array['dasar']::text[], 'Gaji Nia Rp7 juta, tetapi selalu habis sebelum tanggal 20. Ia tidak tahu ke mana uangnya pergi dan belum pernah membuat anggaran.', 'Langkah awal yang paling tepat untuk Nia adalah:', '["Mengajukan kartu kredit untuk menutup sisa bulan.", "Mencatat pengeluaran selama beberapa minggu, lalu menyusun anggaran dan menyisihkan tabungan di awal bulan.", "Meminta kenaikan gaji kepada atasan.", "Mengurangi makan agar uang cukup."]'::jsonb, 1, 'Tanpa catatan, kebocoran pengeluaran sulit dikenali. Setelah polanya terlihat, anggaran dan prinsip "bayar diri sendiri dulu" membantu arus kas tetap positif.', 'Sebelum memperbaiki, kenali dulu ke mana uang keluar.'),
  ('c14', 'Yoga', array['utang']::text[], 'Yoga punya tiga utang: kartu kredit Rp8 juta (bunga 1,75% per bulan), KTA Rp15 juta (bunga 1% per bulan), dan cicilan motor Rp5 juta (bunga 0,8% per bulan). Ia punya dana lebih Rp2 juta per bulan untuk mempercepat pelunasan.', 'Strategi yang membuat total bunga Yoga paling hemat adalah:', '["Mendahulukan cicilan motor karena saldonya paling kecil.", "Mendahulukan kartu kredit karena bunganya paling tinggi.", "Membagi rata dana lebih ke tiga utang.", "Mengambil pinjaman baru untuk menutup semuanya sekaligus."]'::jsonb, 1, 'Metode avalanche mendahulukan utang berbunga tertinggi sehingga total bunga paling kecil. Kartu kredit 1,75% per bulan adalah yang termahal.', 'Bandingkan bunga ketiga utang, bukan saldonya.'),
  ('c15', 'Dewi', array['nabung']::text[], 'Sebuah bank menawari Dewi deposito Rp300 juta dengan bunga jauh di atas tingkat bunga penjaminan LPS. Dewi berpikir semua deposito di bank pasti dijamin.', 'Hal yang perlu Dewi pahami adalah:', '["Semua deposito di bank selalu dijamin LPS berapa pun bunganya.", "Simpanan dengan bunga melebihi tingkat bunga penjaminan LPS tidak termasuk yang dijamin.", "LPS hanya menjamin tabungan, tidak menjamin deposito.", "Penjaminan LPS hanya berlaku untuk nasabah korporasi."]'::jsonb, 1, 'Salah satu syarat penjaminan LPS adalah bunga simpanan tidak melebihi tingkat bunga penjaminan. Bunga yang terlalu tinggi justru membuat simpanan tidak dijamin.', 'Ingat syarat agar simpanan dijamin LPS.'),
  ('c16', 'Arif', array['investasi']::text[], 'Arif berprofil risiko konservatif dan butuh dananya dalam 1 tahun untuk biaya pernikahan. Ia ditawari teman untuk membeli saham yang sedang naik.', 'Pilihan yang paling sesuai untuk Arif adalah:', '["Membeli saham itu karena sedang naik.", "Menempatkan dana di deposito atau reksa dana pasar uang.", "Membeli emas untuk dijual dalam beberapa bulan.", "Meminjam dana tambahan agar bisa membeli lebih banyak saham."]'::jsonb, 1, 'Untuk tujuan 1 tahun dan profil konservatif, nilai dana perlu stabil dan mudah dicairkan. Saham bisa turun tajam dan emas terkena spread untuk jangka pendek.', 'Jangka waktunya pendek dan Arif tidak siap rugi.'),
  ('c17', 'Sinta', array['utang','dasar']::text[], 'Sinta ingin membeli ponsel baru Rp9 juta dengan paylater 12 bulan. Total cicilannya saat ini sudah 28% dari penghasilan bersih, dan ponsel lamanya masih berfungsi baik.', 'Keputusan yang paling tepat adalah:', '["Ambil paylater, cicilan 0% jadi tidak masalah.", "Menunda pembelian dan menabung lebih dulu, karena tambahan cicilan membuat rasio melewati 30% untuk kebutuhan yang tidak mendesak.", "Membeli dengan kartu kredit dan membayar minimum.", "Meminjam dari pinjaman daring agar langsung lunas ke toko."]'::jsonb, 1, 'Tambahan cicilan membuat rasio Sinta melewati batas aman 30%, padahal ponsel bukan kebutuhan mendesak. Menabung dulu menghindari utang konsumtif.', 'Hitung dampaknya pada rasio cicilan dan bedakan kebutuhan dengan keinginan.'),
  ('c18', 'Bagas', array['aman']::text[], 'Bagas ditelepon seseorang yang mengaku petugas bank. Katanya rekening Bagas akan diblokir kecuali ia menyebutkan kode OTP yang baru saja masuk lewat SMS.', 'Tindakan yang paling tepat adalah:', '["Menyebutkan OTP agar rekening tidak diblokir.", "Menyebutkan sebagian OTP saja.", "Menolak memberikan OTP, menutup telepon, lalu menghubungi call center resmi bank.", "Meminta penelepon mengirim OTP baru lewat WhatsApp."]'::jsonb, 2, 'Bank tidak pernah meminta OTP, PIN, atau password. Desakan dan ancaman blokir adalah teknik rekayasa sosial untuk menguras rekening.', 'Siapa yang seharusnya tahu kode OTP rekeningmu?'),
  ('c19', 'Ratna', array['asuransi']::text[], 'Ratna baru menikah dan bekerja sebagai pegawai kontrak. Ia dan suaminya belum memiliki jaminan kesehatan apa pun.', 'Prioritas proteksi yang paling tepat adalah:', '["Asuransi pendidikan anak.", "Jaminan kesehatan dasar seperti BPJS Kesehatan.", "Unit link premi tinggi.", "Asuransi perjalanan luar negeri."]'::jsonb, 1, 'Biaya kesehatan adalah risiko yang paling sering terjadi dan bisa sangat besar. Proteksi kesehatan dasar menjadi pondasi sebelum produk asuransi lain.', 'Asuransi apa yang umumnya dimiliki lebih dulu?'),
  ('c20', 'Joko', array['pensiun','investasi']::text[], 'Joko (30 tahun) bisa menyisihkan Rp500 ribu per bulan untuk masa pensiun. Ia ragu apakah jumlah sekecil itu ada artinya.', 'Saran yang paling tepat untuk Joko adalah:', '["Tunggu sampai bisa menabung Rp2 juta per bulan.", "Mulai sekarang secara rutin, karena waktu yang panjang membuat bunga majemuk bekerja lebih besar.", "Simpan di bawah bantal agar aman.", "Gunakan untuk trading harian agar cepat bertambah."]'::jsonb, 1, 'Semakin panjang waktunya, semakin besar efek bunga majemuk. Setoran kecil yang rutin sejak usia 30 bisa tumbuh signifikan menjelang pensiun.', 'Faktor apa yang paling menentukan hasil bunga majemuk?'),
  ('c21', 'Nina', array['digital']::text[], 'Nina membeli makanan Rp50.000 di sebuah warung dan membayar dengan QRIS. Penjual meminta tambahan Rp1.000 dengan alasan "biaya QRIS".', 'Sikap yang paling tepat bagi Nina adalah:', '["Membayar saja karena memang ada biaya QRIS.", "Menjelaskan dengan sopan bahwa biaya QRIS tidak boleh dibebankan ke pembeli, dan bila perlu melaporkannya.", "Tidak jadi membeli dan memarahi penjual.", "Membayar tunai dan tidak pernah memakai QRIS lagi."]'::jsonb, 1, 'Biaya QRIS (MDR) ditanggung pedagang dan tidak boleh dibebankan ke konsumen. Untuk usaha mikro, transaksi sampai Rp500.000 bahkan bebas MDR.', 'Ingat siapa yang menanggung MDR QRIS menurut ketentuan BI.'),
  ('c22', 'Rudi', array['tujuan','investasi']::text[], 'Anak Rudi berusia 6 tahun. Rudi ingin menyiapkan biaya kuliah anaknya 12 tahun lagi, tetapi belum tahu berapa targetnya. Saat ini biaya kuliah yang diincar sekitar Rp80 juta.', 'Langkah yang paling tepat bagi Rudi adalah:', '["Menabung Rp80 juta di rekening tabungan karena itu biaya kuliahnya.", "Menghitung target dengan memperhitungkan kenaikan biaya pendidikan, lalu berinvestasi rutin di instrumen jangka panjang seperti reksa dana saham atau campuran.", "Menunggu anak SMA baru mulai menabung.", "Membeli saham satu perusahaan yang sedang naik agar cepat terkumpul."]'::jsonb, 1, 'Biaya pendidikan naik setiap tahun sehingga target 12 tahun lagi jauh di atas Rp80 juta. Dengan waktu panjang, investasi rutin yang terdiversifikasi memanfaatkan bunga majemuk.', 'Berapa biaya kuliah 12 tahun lagi jika biayanya naik setiap tahun?'),
  ('c23', 'Mira', array['aman','digital']::text[], 'Mira mengeluh di kolom komentar akun media sosial sebuah bank karena transfernya tertunda. Tidak lama, akun bernama "CS Bank Care 24" mengirim DM dan meminta nomor kartu, tanggal kedaluwarsa, serta kode OTP agar masalahnya cepat diproses.', 'Tindakan yang paling tepat bagi Mira adalah:', '["Memberikan data karena akunnya memakai logo bank.", "Memberikan nomor kartu saja tanpa OTP.", "Tidak memberikan data apa pun dan menghubungi call center resmi bank melalui nomor di situs atau kartu.", "Meminta akun tersebut menelepon agar lebih yakin."]'::jsonb, 2, 'Akun CS palsu sering mengincar orang yang mengeluh di media sosial. Bank resmi tidak meminta data kartu dan OTP lewat DM.', 'Saluran resmi bank bisa dicek di situs dan kartu, bukan dari akun yang menghubungi lebih dulu.')
